create schema if not exists ged;
create extension if not exists pgcrypto;
create table if not exists ged.governance_alert (id uuid primary key default gen_random_uuid(),tenant_id uuid not null,alert_type varchar(80) not null,severity varchar(30) not null default 'MEDIUM',title text not null,description text null,source_type varchar(80) null,source_id uuid null,recommended_action text null,status varchar(40) not null default 'OPEN',assigned_to uuid null,resolved_by uuid null,resolved_at timestamptz null,resolution_notes text null,created_at timestamptz not null default now(),reg_status char(1) not null default 'A');
create table if not exists ged.governance_evidence (id uuid primary key default gen_random_uuid(),tenant_id uuid not null,evidence_code text not null,source_type varchar(80) not null,source_id uuid null,title text not null,description text null,evidence_hash text null,payload_json jsonb null,registered_by uuid null,registered_by_name text null,registered_at timestamptz not null default now(),reg_status char(1) not null default 'A');
create table if not exists ged.governance_report_log (id uuid primary key default gen_random_uuid(),tenant_id uuid not null,report_type varchar(80) not null,report_title text not null,filters_json jsonb null,exported_format varchar(20) null,exported_by uuid null,exported_by_name text null,exported_at timestamptz not null default now(),row_count integer not null default 0,reg_status char(1) not null default 'A');
create table if not exists ged.governance_risk_snapshot (id uuid primary key default gen_random_uuid(),tenant_id uuid not null,documents_without_ocr integer not null default 0,documents_without_classification integer not null default 0,documents_with_sensitive_data integer not null default 0,retention_pending integer not null default 0,boxes_without_location integer not null default 0,overdue_loans integer not null default 0,open_critical_incidents integer not null default 0,overdue_workflow_tasks integer not null default 0,generated_at timestamptz not null default now(),payload_json jsonb null,reg_status char(1) not null default 'A');
create index if not exists ix_governance_alert_status on ged.governance_alert(tenant_id,status,severity,created_at desc) where reg_status='A';
create index if not exists ix_governance_alert_source on ged.governance_alert(tenant_id,source_type,source_id) where reg_status='A';
create unique index if not exists ux_governance_evidence_code on ged.governance_evidence(tenant_id,evidence_code) where reg_status='A';
create index if not exists ix_governance_evidence_source on ged.governance_evidence(tenant_id,source_type,source_id,registered_at desc) where reg_status='A';
create index if not exists ix_governance_report_log_date on ged.governance_report_log(tenant_id,exported_at desc) where reg_status='A';
create index if not exists ix_governance_risk_snapshot_date on ged.governance_risk_snapshot(tenant_id,generated_at desc) where reg_status='A';
